import os


class Config:
    # -------------------------------------------------------------------------
    # Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # File Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the analysis script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output directories
    WORKING_DIR = "./working/idea_10"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # -------------------------------------------------------------------------
    # Data Processing Hyperparameters
    # -------------------------------------------------------------------------
    # Graph Construction
    CUTOFF_RADIUS = 5.0  # Angstroms, strictly set to capture local bonds
    MAX_NEIGHBORS = 50  # Maximum number of neighbors to consider

    # Edge Featurization
    N_RBF = 60  # Number of Gaussian Radial Basis Functions
    RBF_SIGMA = 1.5  # Width of Gaussian functions

    # Global Features
    # Lattice (6) + Composition (4: Al, Ga, In, O)
    GLOBAL_FEATURES_DIM = 10

    # -------------------------------------------------------------------------
    # Model Architecture Hyperparameters
    # -------------------------------------------------------------------------
    ATOM_EMBEDDING_DIM = 64
    HIDDEN_DIM = 64
    N_LAYERS = 4  # Number of interaction layers in CGCNN backbone
    DROPOUT = 0.1
    ACTIVATION = "softplus"  # Standard for crystal graph networks

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 48  # Selected to introduce beneficial gradient noise
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4  # Regularization
    NUM_EPOCHS = 100
    PATIENCE = 15  # Early stopping patience

    # -------------------------------------------------------------------------
    # Debugging and Development
    # -------------------------------------------------------------------------
    DEBUG = False
    # If set to an integer (e.g., 100), only this many samples will be used
    SAMPLE_SIZE = None

    @classmethod
    def setup_directories(cls):
        """Creates necessary output directories if they don't exist."""
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.CHECKPOINT_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
